definition:
\foreach \p/\i/\lbl in {horizontal lines/0/horiz, vertical lines/1/vert,
                        crosshatch/2/crosshatch, dots/3/dots, bricks/4/bricks} {
  \draw[pattern=\p,draw=black,thick] (\i*1.6,0) rectangle (\i*1.6+1.3,1.3);
  \node[below,font=\small] at (\i*1.6+0.65,-0.05) {\lbl};
}
\draw[pattern=crosshatch dots,draw=black,thick] (0,2) rectangle (2.9,3);
\node[right,font=\small] at (3.1,2.5) {crosshatch dots};
